import org.apache.commons.lang.StringUtilsimport org.marker.mushroom.alias.DAOimport org.marker.mushroom.core.config.impl.DataBaseConfigimport org.marker.mushroom.dao.ISupportDaoimport org.marker.mushroom.ext.plugin.Pluginletimport org.marker.mushroom.holder.SpringContextHolderimport org.marker.mushroom.utils.ResultUtilsimport org.springframework.web.bind.annotation.ResponseBodyimport javax.servlet.http.HttpServletRequestimport javax.servlet.http.HttpServletResponse/** * 留言插件 * * * @author marker * */public class PanchaPluginletImpl extends Pluginlet {    PanchaPluginletImpl() {        this._config = [                module     : "pancha",                name       : "盘查插件",                author     : "marker",                type       : "pancha",// 模型标识                description: "常规插件"        ]        // 路由配置        this.routers = [                " get:/list" : "list",                "post:/add"  : "submit",                " get:/edit": "edit",                "post:/update": "update",        ]    }    /**     * 显示留言列表     */    String list() {        HttpServletRequest request = getServletRequest();        int currentPageNo = 1;        try {            currentPageNo = Integer.parseInt(request.getParameter("currentPageNo"));        } catch (Exception e) {        }        ISupportDao dao = SpringContextHolder.getBean(DAO.COMMON);        DataBaseConfig dbcfg = DataBaseConfig.getInstance();        String prefix = dbcfg.getPrefix();        String sql = """select a.*,p.keywords pKeywords,p.type as pType, p.pwd from ${prefix}article a                 left join ${prefix}pancha p on a.id = p.article_id                 order by a.id desc                """;        request.setAttribute("page", dao.findByPage(currentPageNo, 15, sql));        return "list.html";    }    /**     * 提交     */    @ResponseBody    def submit() {        HttpServletRequest request = getServletRequest();        HttpServletResponse response = getServletResponse();        String code = request.getParameter("authcode");// 验证码        String randauthcode = (String) request.getSession().getAttribute("randauthcode");        String ip = request.getRemoteHost();        String nickname = request.getParameter("nickname");        String email = request.getParameter("email");        String content = request.getParameter("content");        if (StringUtils.isBlank(email)) {            return ResultUtils.error("请填写邮箱地址")        }        if (StringUtils.isBlank(content)) {            return ResultUtils.error("请填写留言内容")        }        DataBaseConfig dbcfg = DataBaseConfig.getInstance();        String msg = "提交成功";//		if(!Object.equals(randauthcode, code)){//			return ResultUtils.error("验证码错误！")//		}        String sql = "insert into " + dbcfg.getPrefix() + "pancha(email, nickname,ip,content,time,status) values(?,?,?,?,sysdate(),0)";        def strs = [email, nickname, ip, content] as Object[];        if (!commonDao.update(sql, strs)) {            return ResultUtils.error("留言信息无效！")        }        return ResultUtils.success(msg)    }    /**     * 留言审核     */    @ResponseBody    def audit() {        HttpServletRequest request = getServletRequest();        String idStr = request.getParameter("id");// id        int id = Integer.parseInt(idStr);        DataBaseConfig dbcfg = DataBaseConfig.getInstance();        String sql = "update " + dbcfg.getPrefix() + "pancha set status=1 where id=?";        Object[] params = [id] as Object[]        if (!commonDao.update(sql, params)) {            return ResultUtils.error("审核失败！")        }        return ResultUtils.success("审核成功！")    }    /**     * 更新盘查     * @return     */    @ResponseBody    def update() {        HttpServletRequest request = getServletRequest();        String idStr = request.getParameter("id");// id        String pKeywords = request.getParameter("pKeywords");// id        String pType = request.getParameter("pType");// id        String pPwd = request.getParameter("pPwd");// id        int id = Integer.parseInt(idStr);        // TODO keywords 验重复        DataBaseConfig dbcfg = DataBaseConfig.getInstance();        String prefix = dbcfg.getPrefix();        Map<String,Object> entity = getOne(id);        if(entity != null && StringUtils.isNotBlank(entity.get("pId"))){ // 数据存在则更新            String sql = "update " + dbcfg.getPrefix() + "pancha set status=1,keywords=?,type=?,pwd=?,article_id=? where id=?";            Object[] params = [pKeywords,pType,pPwd,id,id] as Object[]            if (commonDao.update(sql, params)) {                return ResultUtils.success("成功！")            }        }else{            String sql = "insert into " + dbcfg.getPrefix() + "pancha(id,keywords,type,pwd,article_id, create_time) values(?,?,?,?,?, sysdate())";            Object[] params = [id, pKeywords,pType,pPwd,id] as Object[]            if (commonDao.update(sql, params)) {                return ResultUtils.success("成功！")            }        }        return ResultUtils.error("失败！")    }    /**     * 编辑盘查     */    String edit() {        HttpServletRequest request = getServletRequest();        String idStr = request.getParameter("id");// id        int id = Integer.parseInt(idStr);        request.setAttribute("article", getOne(id));         return "edit.html";    }    /**     * 前端留言组件     */    def view() {        HttpServletRequest request = getServletRequest();        return "guestbook.html";    }    // ============== 持久层 ==============    def getOne(Integer id){        DataBaseConfig dbcfg = DataBaseConfig.getInstance();        String prefix = dbcfg.getPrefix();        String sql = """select a.*,p.id as pId,p.keywords pKeywords,p.type as pType, p.pwd as pPwd from ${prefix}article a                 left join ${prefix}pancha p on a.id = p.article_id                 where a.id = ?                 order by a.id desc                """;        Object[] params = [id] as Object[]        return commonDao.queryForMap(sql, params);    }}